import static org.junit.Assert.assertNull;

public class Element_previousElementSibling_TriageGen0Test {

    @Test
    public void test_previousElementSibling_noSiblings() {
        // Given
        Element element = new Element(new Tag("div"), "", new Attributes());
        element.parent().appendChild(element);

        // When
        Element previousSibling = element.previousElementSibling();

        // Then
        assertNull(previousSibling);
    }

    @Test
    public void test_previousElementSibling_singleSibling() {
        // Given
        Element element = new Element(new Tag("div"), "", new Attributes());
        Element sibling = new Element(new Tag("p"), "", new Attributes());
        element.parent().appendChild(element);
        element.parent().appendChild(sibling);

        // When
        Element previousSibling = element.previousElementSibling();

        // Then
        assertEquals(sibling, previousSibling);
    }

    @Test
    public void test_previousElementSibling_multipleSiblings() {
        // Given
        Element element = new Element(new Tag("div"), "", new Attributes());
        Element sibling1 = new Element(new Tag("p"), "", new Attributes());
        Element sibling2 = new Element(new Tag("span"), "", new Attributes());
        element.parent().appendChild(element);
        element.parent().appendChild(sibling1);
        element.parent().appendChild(sibling2);

        // When
        Element previousSibling = element.previousElementSibling();

        // Then
        assertEquals(sibling1, previousSibling);
    }

    @Test
    public void test_previousElementSibling_nullParent() {
        // Given
        Element element = new Element(new Tag("div"), "", new Attributes());

        // When
        Element previousSibling = element.previousElementSibling();

        // Then
        assertNull(previousSibling);
    }

    @Test
    public void test_previousElementSibling_indexOutofBounds() {
        // Given
        Element element = new Element(new Tag("div"), "", new Attributes());
        Element sibling = new Element(new Tag("p"), "", new Attributes());
        element.parent().appendChild(element);
        element.parent().appendChild(sibling);

        // When
        Element previousSibling = sibling.previousElementSibling();

        // Then
        assertNull(previousSibling);
    }
}
